# ---------------------------------------------------------------- auth, project, API keys


class Auth:
    """Sign-up and console logins. Server-side code uses an API key instead of logging in."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def signup(
        self,
        email: str,
        password: str,
        *,
        accept_terms: bool,
        name: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.SignupResponse:
        """Creates a user, a project on the Free plan and a first API key (in the response only). No API key needed.

        ``accept_terms=True`` says the user accepts the terms of service and acceptable use policy (400
        ``terms_not_accepted`` without it); ``name`` is optional."""
        body: Dict[str, Any] = {"email": email, "password": password, "acceptTerms": accept_terms}
        if name is not None:
            body["name"] = name
        return self._c._json("POST", "/v1/auth/signup", json=body, options=options)

    def login(self, email: str, password: str, *, options: Optional[RequestOptions] = None) -> t.LoginResponse:
        """Starts a console login: the cookie is kept by this client, so later calls act as that user."""
        return self._c._json("POST", "/v1/auth/login", json={"email": email, "password": password}, options=options)

    def logout(self, *, options: Optional[RequestOptions] = None) -> None:
        """Ends the console login."""
        self._c._json("POST", "/v1/auth/logout", options=options)


class Project:
    """Project settings."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def settings(self, *, options: Optional[RequestOptions] = None) -> t.ProjectSettings:
        """The project's settings: ``captchaDefault`` is what new sessions and agent runs without a ``captcha`` option
        get; ``captchaDefaultEffective`` what they get now (the plan may no longer include solving); ``trajectories`` the
        Trajectories program setting ``{"enabled", "noticeSeenAt", "decidedBy"}`` (on by default; see the Terms of Service
        and Privacy Policy)."""
        return self._c._json("GET", "/v1/project/settings", options=options)

    def set_settings(
        self,
        captcha_default: Optional[str] = None,
        default_model: Any = NOT_GIVEN,
        trajectories: Optional[t.TrajectoriesChange] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.ProjectSettings:
        """Changes the fields you pass (``captcha_default="solve"`` needs a plan with CAPTCHA solving: 402 otherwise).
        ``default_model={"provider": "openai", "model": "gpt-6-luna"}`` is the model used when a request names none;
        ``default_model=None`` clears it. ``trajectories={"enabled": False}`` turns the Trajectories program off for this
        project (the choice is logged; ``"source"`` is "notice" or "settings", the default)."""
        body: Dict[str, Any] = clean({"captchaDefault": captcha_default, "trajectories": trajectories})
        if default_model is not NOT_GIVEN:
            body["defaultModel"] = default_model  # None clears it
        return self._c._json("PUT", "/v1/project/settings", json=body, options=options)

    def model_keys(self, *, options: Optional[RequestOptions] = None) -> t.ModelKeys:
        """The four providers with the project's own-key state: ``{"keys": [{"provider", "use", "useEffective", "hasKey",
        "preview", ...}]}``. A key is never returned; ``preview`` is its last 4 characters."""
        return self._c._json("GET", "/v1/project/model-keys", options=options)

    def set_model_key(
        self,
        provider: t.Provider,
        key: Optional[str] = None,
        use: Optional[t.KeySource] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.ModelKey:
        """Saves a provider key and/or the choice of whose key calls use (``use="project"`` needs a saved key,
        ``use="platform"`` a plan with ``platformModels``: 402 otherwise). The provider checks the key first (400
        ``invalid_model_key``). Runs on your own key have no model charge from Boxline."""
        return self._c._json("PUT", f"/v1/project/model-keys/{provider}", json=clean({"key": key, "use": use}), options=options)

    def delete_model_key(self, provider: t.Provider, *, options: Optional[RequestOptions] = None) -> None:
        """Deletes the provider's key; calls go back to the platform's key where the plan includes it."""
        self._c._json("DELETE", f"/v1/project/model-keys/{provider}", options=options)


class ApiKeys:
    """The project's API keys."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.ApiKey]:
        """Active keys, oldest first (the keys themselves are never shown again; ``prefix`` identifies them)."""
        return self._c._list("/v1/project/api-keys", {"limit": limit, "after": after}, lambda k: k, options)

    def create(self, name: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.NewApiKey:
        """A new key; ``key`` is in this response only."""
        return self._c._json("POST", "/v1/project/api-keys", json=clean({"name": name}), options=options)

    def revoke(self, key_id: str, *, options: Optional[RequestOptions] = None) -> None:
        self._c._json("DELETE", f"/v1/project/api-keys/{seg(key_id)}", options=options)


# ---------------------------------------------------------------- sessions


class Sessions:
    """Sessions: one isolated machine each, with a browser and/or a shell and a shared /workspace disk."""

    def __init__(self, client: Boxline) -> None:
        self._c = client
        self.files = SessionFiles(client)

    def _wrap(self, data: Any) -> "Session":
        return Session(self._c, data)

    def _one(self, method: str, path: str, body: Any = None, options: Optional[RequestOptions] = None) -> "Session":
        return self._wrap(self._c._json(method, path, json=body, options=options))

    def create(
        self,
        browser: bool = True,
        shell: bool = False,
        timeout: Optional[int] = None,
        keep_alive: Optional[bool] = None,
        viewport: Optional[Dict[str, int]] = None,
        user_metadata: Optional[JSON] = None,
        profile: Optional[Union[str, JSON]] = None,
        persist_profile: bool = False,
        record_session: Optional[bool] = None,
        setup: Optional[Sequence[str]] = None,
        proxy: Optional[Proxy] = None,
        captcha: Optional[str] = None,
        browser_options: Optional[JSON] = None,
        block_ads: Optional[bool] = None,
        cookie_banners: Optional[str] = None,
        extensions: Optional[Sequence[str]] = None,
        env: Optional[Dict[str, Union[str, int, float, bool]]] = None,
        credentials: Optional[Sequence[str]] = None,
        idle_timeout: Optional[int] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> "Session":
        """Starts a session (an Idempotency-Key is sent, so a retry never starts a second one): a browser (the default),
        a shell (``browser=False, shell=True``) or both (``shell=True``). Agent runs and tasks take the same settings as
        a ``session`` dict (``types.SessionSpec``, with the API's names).

        ``timeout`` is the session's length in seconds (default 300). ``idle_timeout`` (opt-in, 30 to ``timeout``): the
        session ends (end reason ``idle``) after that many seconds without activity (CDP commands, live-view input,
        terminal keys, exec, files, actions and steps, scripts, agent steps and messages; an agent run working in it, or
        one that can still be resumed, counts the whole time). ``profile`` is a browser profile's id (or
        ``{"id": ..., "persist": True}``) to start from its cookies and local storage; ``setup`` lists shell commands
        (package installs) run at start.

        ``proxy`` sends the session's traffic through a proxy:
        ``{"type": "residential", "country": "US", "state": "us_california", "city": "los_angeles"}``,
        ``{"type": "datacenter", "country": "DE"}`` or ``{"type": "custom", "server": "http://host:port",
        "username": ..., "password": ...}``; plus ``"ip": "sticky" | "rotating"`` and ``"scope": "browser" | "all"``
        (all = the shell uses it too). ``True`` means a residential US proxy. A list of rules picks a proxy per
        site: each rule may have a ``"domainPattern"`` (a regular expression tested against the host name), the
        first match wins, ``{"type": "none"}`` goes straight out, and no match goes straight out.

        ``captcha``: when a CAPTCHA waits for a person, ``"ask"`` (default) pauses agent runs and plain-English
        steps until someone solves it in the live view; ``"ignore"`` lets them carry on; ``"solve"`` has the
        platform try to solve it automatically and falls back to ``"ask"`` on failure. Either way the session's
        ``attention`` and its ``captcha`` events report it (see ``Session.wait_for_human``). Only enable ``"solve"``
        for sites you are authorised to automate.

        ``browser_options``: ``{"mode": "realistic"}`` puts the browser's clock and language on the proxy's
        country; ``{"locale": "de-DE", "timezone": "Europe/Berlin"}`` sets them yourself. It never changes what the
        browser reports about itself.

        ``block_ads=True`` refuses requests to ad and tracker sites inside the machine (``blocked_requests`` counts
        them); ``cookie_banners`` is ``"reject"`` (the default: "Reject all" / "Necessary only", never accept) or
        ``"off"``; ``extensions`` are uploaded extension ids (``extensions.upload``, at most 10, set at start only).
        An extension sees every page and every typed value in the session: use only ones you trust.

        ``env`` (needs ``shell=True``): variables for the session's shell, ``{"NAME": "value"}``: new terminals, exec,
        scripts and ``setup`` commands get them, and they are set again on every new machine (resume, recovery).
        Names like the shell's (not PATH, HOME or BOXLINE_*), at most 100, 64 KB together; the session shows the names
        only. ``credentials`` (needs ``shell=True``): credentials exported into the shell (scope "shell" or "all", or
        ``shell: True``; CredentialNotAllowedError otherwise): a secret as ``$NAME``, a password as ``$NAME_USERNAME``
        and ``$NAME_PASSWORD`` (its 2FA code comes from ``boxline-otp NAME``; the key itself never enters the machine).
        Kept in the machine's memory only and hidden in exec, script and terminal output. Anything that runs in the
        shell can read them: export only what you accept that for."""
        ctx = {"id": profile, "persist": persist_profile} if isinstance(profile, str) else profile
        body = clean(
            {
                "browser": browser_options if browser_options is not None else browser,
                "shell": shell,
                "timeout": timeout,
                "keepAlive": keep_alive,
                "viewport": viewport,
                "userMetadata": user_metadata,
                "profile": ctx,
                "recordSession": record_session,
                "setup": as_list(setup),
                "proxy": proxy,
                "captcha": captcha,
                "blockAds": block_ads,
                "cookieBanners": cookie_banners,
                "extensions": as_list(extensions),
                "env": env,
                "credentials": as_list(credentials),
                "idleTimeout": idle_timeout,
            }
        )
        return self._one("POST", "/v1/sessions", body, options)

    def get(self, session_id: str, *, options: Optional[RequestOptions] = None) -> "Session":
        """The session, with freshly signed ``connectUrl``, ``liveUrl`` and ``terminalUrl`` every time (None where the
        session has no browser or shell, or is not running)."""
        return self._one("GET", f"/v1/sessions/{seg(session_id)}", None, options)

    def list(
        self,
        status: Optional[Union[str, Sequence[str]]] = None,
        kind: Optional[str] = None,
        q: Optional[str] = None,
        from_: Optional[str] = None,
        to: Optional[str] = None,
        sort: Optional[str] = None,
        limit: Optional[int] = None,
        after: Optional[str] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> Pager["Session"]:
        """Sessions, newest first unless ``sort`` says otherwise (``created_asc``, ``duration_desc``). ``status``: one or
        several (``["RUNNING", "STOPPED"]``); ``kind``: ``browser``, ``combined`` or ``shell``; ``q``: an id prefix or
        text in ``userMetadata``. Iterate for every session; the first page's ``total`` counts every match."""
        params = {"status": status, "kind": kind, "q": q, "from": from_, "to": to, "sort": sort, "limit": limit, "after": after}
        return self._c._list("/v1/sessions", params, self._wrap, options)

    def bulk(self, action: str, ids: Sequence[str], *, options: Optional[RequestOptions] = None) -> t.BulkResult:
        """Stop, resume or delete 1 to 100 sessions at once (``action``: "stop", "resume" or "delete"; ``ids`` are
        session ids; 30 calls per minute per project)."""
        return self._c._json("POST", "/v1/sessions/bulk", json={"action": action, "ids": list(ids)}, options=options)

    def update(
        self,
        session_id: str,
        keep_alive: Optional[bool] = None,
        user_metadata: Optional[JSON] = None,
        captcha: Optional[str] = None,
        browser: Optional[JSON] = None,
        proxy: Any = NOT_GIVEN,
        block_ads: Optional[bool] = None,
        cookie_banners: Optional[str] = None,
        idle_timeout: Any = NOT_GIVEN,
        timeout: Optional[int] = None,
        rotate_proxy: Optional[bool] = None,
        rotate_urls: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> "Session":
        """The one call that changes a running session, with the argument names ``create`` has: ``keep_alive``,
        ``timeout`` (its length in seconds, counted from its last start; at least 60 s from now, at most the plan's
        maximum: PlanLimitError), ``idle_timeout`` (seconds, counted from now; ``None`` switches it off), ``user_metadata``,
        ``proxy`` (``None`` removes it; a new one applies at once), ``captcha``, ``browser`` settings (``mode``,
        ``locale``, ``timezone``), ``block_ads`` and ``cookie_banners`` (both at once), plus ``rotate_proxy=True`` (a new
        proxy IP now; 400 without a proxy) and ``rotate_urls=True`` (new signed connect, live and terminal URLs: every
        earlier one stops working). What is fixed when the session is created (``browser`` or ``shell`` on or off,
        viewport, profile, record_session, setup, extensions, env, credentials) is not here: NotUpdatableError.
        SessionNotRunningError for a session that is not running."""
        body = clean(
            {
                "keepAlive": keep_alive,
                "timeout": timeout,
                "userMetadata": user_metadata,
                "captcha": captcha,
                "browser": browser,
                "blockAds": block_ads,
                "cookieBanners": cookie_banners,
                "rotateProxy": rotate_proxy,
                "rotateUrls": rotate_urls,
            }
        )
        if proxy is not NOT_GIVEN:
            body["proxy"] = proxy
        if idle_timeout is not NOT_GIVEN:
            body["idleTimeout"] = idle_timeout
        return self._one("PATCH", f"/v1/sessions/{seg(session_id)}", body, options)

    def stop(self, session_id: str, *, options: Optional[RequestOptions] = None) -> "Session":
        """Saves the session exactly as it is (the whole browser, every tab with its history, and the files), frees the
        machine and stops billing. It is kept for the plan's ``retentionDays`` (``deletesAt``), then deleted: resume it before."""
        return self._one("POST", f"/v1/sessions/{seg(session_id)}/stop", None, options)

    def resume(self, session_id: str, *, options: Optional[RequestOptions] = None) -> "Session":
        """Brings a stopped session back on a fresh machine, as it was (same id; 409 ``nothing_saved`` when nothing was saved)."""
        return self._one("POST", f"/v1/sessions/{seg(session_id)}/resume", None, options)

    def delete(self, session_id: str, *, options: Optional[RequestOptions] = None) -> "Session":
        """Ends the session for good: what it saved, its recording and its logs are deleted now. It cannot be undone."""
        return self._one("DELETE", f"/v1/sessions/{seg(session_id)}", None, options)

    def actions(self, session_id: str, actions: Union[ActionItem, Sequence[ActionItem]], timeout_ms: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> List[t.ActionResult]:
        """Runs browser actions in order, next to the browser, e.g. ``[{"action": "goto", "url": ...}, "click Sign in",
        {"action": "content"}]`` (a bare string is a plain-English step); stops at the first failure. Each result's
        ``text`` says what happened. BrowserDisabledError (409) on a session created with ``browser=False``."""
        items = [actions] if isinstance(actions, (dict, str)) else list(actions)
        wait = actions_wait(items)
        r = self._c._json("POST", f"/v1/sessions/{seg(session_id)}/browser/actions", json=clean({"actions": items, "timeoutMs": timeout_ms}), options=options, timeout=wait)
        return r["results"]

    def computer(
        self,
        session_id: str,
        action: JSON,
        max_width: Optional[int] = None,
        screenshot: Optional[bool] = None,
        format: Optional[str] = None,
        quality: Optional[int] = None,
        cursor: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.ComputerResult:
        """Runs ONE computer-use action exactly as the model's tool gave it (Anthropic ``computer`` tool input, e.g.
        ``{"action": "left_click", "coordinate": [512, 300]}``, or one OpenAI ``computer_call`` action, e.g. ``{"type":
        "click", "x": 512, "y": 300, "button": "left"}``) on the session's page, and returns the screen after it. With
        ``max_width`` the screenshot is scaled down and the action's coordinates are read in its pixels (send the same
        value on every call). A failure in the page is ``ok: False``; input that cannot be mapped, or a point off the
        screen, raises (400 ``invalid_request`` / ``out_of_viewport``)."""
        body = {**action, **clean({"maxWidth": max_width, "screenshot": screenshot, "format": format, "quality": quality, "cursor": cursor})}
        return self._c._json("POST", f"/v1/sessions/{seg(session_id)}/browser/computer", json=body, options=options)

    def exec(
        self,
        session_id: str,
        command: str,
        timeout_ms: Optional[int] = None,
        cwd: Optional[str] = None,
        env: Optional[Dict[str, str]] = None,
        shell: Optional[Union[str, bool]] = None,
        credentials: Optional[Sequence[str]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.ExecResult:
        """Runs a command in the session's shell (persistent bash by default: cd/export survive). ``shell=False`` runs it in
        a fresh process. ShellDisabledError (409) on a session created without ``shell=True``.
        ``cwd``, ``env`` and ``credentials`` (credentials as environment variables, scope "shell" or "all": a secret
        as ``$NAME``, a password as ``$NAME_USERNAME`` and ``$NAME_PASSWORD``, and ``boxline-otp NAME`` prints its 2FA
        code) apply to this command only; the session's exported credentials and these are hidden in the output as
        ``%NAME%``."""
        body = clean({"command": command, "timeoutMs": timeout_ms, "cwd": cwd, "env": env, "shell": shell, "credentials": as_list(credentials)})
        return self._c._json("POST", f"/v1/sessions/{seg(session_id)}/shell/exec", json=body, options=options, timeout=(timeout_ms or 120_000) / 1000 + 30 + SETUP_WAIT_S)

    def exec_stream(
        self,
        session_id: str,
        command: str,
        timeout_ms: Optional[int] = None,
        cwd: Optional[str] = None,
        env: Optional[Dict[str, str]] = None,
        shell: Optional[Union[str, bool]] = None,
        credentials: Optional[Sequence[str]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> "ExecStream":
        """Runs a command and streams its output (see ``ExecStream``); ``credentials`` as for ``exec``."""
        body = clean({"command": command, "timeoutMs": timeout_ms, "cwd": cwd, "env": env, "shell": shell, "credentials": as_list(credentials), "stream": True})
        return ExecStream(self._c._stream("POST", f"/v1/sessions/{seg(session_id)}/shell/exec", json=body, options=options))

    def run_script(
        self,
        session_id: str,
        code: str,
        env: Optional[Dict[str, str]] = None,
        timeout_ms: Optional[int] = None,
        ai: Optional[Dict[str, str]] = None,
        credentials: Optional[Sequence[str]] = None,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> "ExecStream":
        """Runs Playwright (JavaScript) code inside the session (needs a browser and a shell), streaming its output. In scope:
        ``page``, ``context``, ``browser``, ``env`` and the AI helpers ``step()``, ``extract()`` and
        ``useModel(model)`` / ``useModel(provider, model)``. A step or extract uses the call's own
        ``{provider, model}``, else the last ``useModel()``, else ``ai`` (``{"provider": ..., "model": ...}``), else
        the platform default.

        ``credentials``: credentials the script's ``step()`` calls may use as placeholders (scope "agent" or "all");
        the values never enter the machine, and the grant is for this run only. A credential the session's profile links
        is used only when it is listed here. In a session with Chrome extensions they need
        ``allow_with_extensions=True`` (VariablesWithExtensionsError otherwise)."""
        body = clean({"code": code, "env": env, "timeoutMs": timeout_ms, "ai": ai, "credentials": as_list(credentials), "allowWithExtensions": allow_with_extensions})
        return ExecStream(self._c._stream("POST", f"/v1/sessions/{seg(session_id)}/browser/script", json=body, options=options))

    def restart_shell(self, session_id: str, name: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> None:
        """Restarts the persistent shell (or the named one)."""
        self._c._json("POST", f"/v1/sessions/{seg(session_id)}/shell/restart", json=clean({"shell": name}), options=options)

    def export_cookies(self, session_id: str, path: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.CookieFile:
        """Writes the browser's cookies as a Netscape cookie file in the workspace (for curl -b / wget)."""
        return self._c._json("POST", f"/v1/sessions/{seg(session_id)}/browser/export-cookies", json=clean({"path": path}), options=options)

    def events(
        self,
        session_id: str,
        types: Optional[Sequence[str]] = None,
        after: Optional[Union[int, str]] = None,
        limit: Optional[int] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> Pager[t.SessionEvent]:
        """Console, network, navigation, error, lifecycle, action, exec and captcha events, oldest first. Every shell
        command is an ``exec`` event, whoever ran it: ``data["by"]`` is ``api``, ``agent`` (with ``data["runId"]``),
        ``setup`` or ``script``. Iterating stops once caught up; ``page.next_after`` is the ``after`` to poll with later."""
        return self._c._list(f"/v1/sessions/{seg(session_id)}/events", {"types": as_list(types), "after": after, "limit": limit}, lambda e: e, options)

    def stream_events(self, session_id: str, after: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> Iterator[t.SessionEvent]:
        """Events as they happen: first the backlog after ``after``, then live, until you stop iterating."""
        res = self._c._stream("GET", f"/v1/sessions/{seg(session_id)}/events/stream", params={"after": after}, options=options)
        try:
            for event in _sse(res.iter_lines()):
                yield event  # type: ignore[misc]
        finally:
            res.close()

    def pages(self, session_id: str, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.VisitedPage]:
        """Pages visited, grouped by tab and URL, in the order they were first visited."""
        return self._c._list(f"/v1/sessions/{seg(session_id)}/pages", {"limit": limit, "after": after}, lambda p: p, options)

    def recording(self, session_id: str, *, options: Optional[RequestOptions] = None) -> t.Recording:
        """Replay frames kept while the session ran: ``{"frames": [{"index", "at", "url"}], "durationMs"}``."""
        return self._c._json("GET", f"/v1/sessions/{seg(session_id)}/recording", options=options)

    def recording_frame(self, session_id: str, index: int, *, options: Optional[RequestOptions] = None) -> bytes:
        """One replay frame as JPEG bytes."""
        return self._c._bytes("GET", f"/v1/sessions/{seg(session_id)}/recording/frames/{int(index)}", options=options)


class SessionFiles:
    """Files in a session's /workspace, shared by the shell and the browser's downloads folder. Every kind of session has
    them. Reading a file, listing a folder and downloading a folder (``archive``) also work on a STOPPED session,
    read-only and without starting a machine, until the session is deleted: they are served from the workspace it saved
    (NothingSavedError when it saved none). Writing, deleting and waiting for a file need a running session
    (SessionNotRunningError)."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def list(self, session_id: str, path: str = ".", *, options: Optional[RequestOptions] = None) -> List[t.FileEntry]:
        """The entries of a folder (``"."`` is the workspace): ``[{"name", "type", "size", "mtime"}]``. Also on a stopped
        session."""
        r = self._c._json("GET", f"/v1/sessions/{seg(session_id)}/files", params={"path": path, "list": "1"}, options=options)
        return r["entries"]

    def read(self, session_id: str, path: str, *, options: Optional[RequestOptions] = None) -> bytes:
        """A file's bytes. Also on a stopped session."""
        return self._c._bytes("GET", f"/v1/sessions/{seg(session_id)}/files", params={"path": path}, options=options)

    def archive(self, session_id: str, path: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> bytes:
        """A folder and everything in it as one ``.tar.gz`` (the bytes): everything an agent made, in one call (``path``
        defaults to the whole workspace; ``.boxline/`` is left out and links are stored as links, never followed). Also
        on a stopped session. At most 1 GiB and 100,000 entries (ArchiveTooLargeError, before any byte is sent);
        NotADirectoryError for a file, InvalidPathError for a path outside the workspace, ArchiveBusyError when two
        archives of the session are being made."""
        return self._c._bytes("GET", f"/v1/sessions/{seg(session_id)}/files/archive", params={"path": path}, options=options)

    def read_text(self, session_id: str, path: str, encoding: str = "utf-8", *, options: Optional[RequestOptions] = None) -> str:
        return (self.read(session_id, path, options=options)).decode(encoding)

    def write(self, session_id: str, path: str, data: Union[str, bytes], *, options: Optional[RequestOptions] = None) -> t.FileRef:
        """Writes a file (folders are made as needed). Running sessions only."""
        content = data.encode() if isinstance(data, str) else data
        res = self._c._send("PUT", f"/v1/sessions/{seg(session_id)}/files", content=content, params={"path": path}, options=options)
        return _parse(res)

    def delete(self, session_id: str, path: str, *, options: Optional[RequestOptions] = None) -> None:
        self._c._json("DELETE", f"/v1/sessions/{seg(session_id)}/files", params={"path": path}, options=options)

    def wait_for(self, session_id: str, pattern: str, timeout_ms: int = 30_000, *, options: Optional[RequestOptions] = None) -> t.FileRef:
        """Waits for a file matching a glob (e.g. ``downloads/*.csv``) that has finished writing."""
        return self._c._json("GET", f"/v1/sessions/{seg(session_id)}/files/wait", params={"pattern": pattern, "timeoutMs": timeout_ms}, options=options, timeout=timeout_ms / 1000 + 30)


class ExecStream:
    """Output of a streaming command or script. Iterate for ``(stream, text)`` pairs; ``result`` holds the exit
    information afterwards. ``close()`` (or leaving the ``with`` block early) stops the command::

        proc = s.exec_stream("npm install")
        with proc:
            for stream, text in proc:
                print(text, end="")
        print(proc.result["exitCode"])
    """

    def __init__(self, response: httpx.Response) -> None:
        self._res = response
        self._done = False
        self.result: Optional[t.ExecExit] = None

    def __iter__(self) -> Iterator[Tuple[str, str]]:
        if self._done:
            return
        try:
            for line in self._res.iter_lines():
                msg = json_line(line)
                if msg is None:
                    continue
                if msg.get("type") == "exit":
                    self.result = msg  # type: ignore[assignment]
                elif msg.get("type") in ("stdout", "stderr"):
                    yield msg["type"], msg.get("data", "")
                elif msg.get("type") == "error":  # after the headers went out (e.g. the machine could not be reached)
                    raise make_error(msg.get("status") or 500, msg.get("code") or "internal", msg.get("message") or "the command failed", request_id=msg.get("requestId"))
                # "waiting" (for the session's setup) and "ping" lines only keep the connection open
        finally:
            self._done = True
            self._res.close()

    def wait(self) -> t.ExecExit:
        """Consumes the rest of the output and returns the exit information."""
        for _ in self:
            pass
        return self.result or {"exitCode": None, "timedOut": False}

    def close(self) -> None:
        self._done = True
        self._res.close()

    def __enter__(self) -> "ExecStream":
        return self

    def __exit__(self, *exc: Any) -> None:
        self.close()


# ---------------------------------------------------------------- one session


class Session:
    """A running (or stopped) session. Attributes mirror the API: ``id``, ``status``, ``connect_url``,
    ``live_url``, ``terminal_url``, ``workspace_path`` (and any other field in snake_case); ``data`` has the full
    record. Leaving the ``with`` block stops it."""

    def __init__(self, client: Boxline, data: t.SessionData) -> None:
        self._c = client
        self.data = data
        self.files = Files(self)
        self.mouse = Mouse(self)
        self.keyboard = Keyboard(self)

    @property
    def id(self) -> str:
        return self.data["id"]

    @property
    def status(self) -> str:
        return self.data["status"]

    @property
    def connect_url(self) -> Optional[str]:
        """WebSocket URL for Playwright/Puppeteer ``connect_over_cdp``. Treat it like a password."""
        return self.data.get("connectUrl")

    @property
    def live_url(self) -> Optional[str]:
        return self.data.get("liveUrl")

    @property
    def terminal_url(self) -> Optional[str]:
        return self.data.get("terminalUrl")

    @property
    def workspace_path(self) -> str:
        return self.data.get("workspacePath", "/workspace")

    def __getattr__(self, name: str) -> Any:
        data = self.__dict__.get("data") or {}
        key = camel(name)
        if key in data:
            return data[key]
        raise AttributeError(name)

    def __repr__(self) -> str:
        return f"Session(id={self.data.get('id')!r}, status={self.data.get('status')!r})"

    def __enter__(self) -> "Session":
        return self

    def __exit__(self, *exc: Any) -> None:
        if self.data.get("status") == "RUNNING":
            try:
                self.stop()
            except BoxlineError:
                pass

    def _set(self, other: "Session") -> "Session":
        self.data = other.data
        return self

    # ----- lifecycle

    def refresh(self, *, options: Optional[RequestOptions] = None) -> "Session":
        return self._set(self._c.sessions.get(self.id, options=options))

    def stop(self, *, options: Optional[RequestOptions] = None) -> "Session":
        """Saves the session exactly as it is (the whole browser and the files), frees the machine, stops billing."""
        return self._set(self._c.sessions.stop(self.id, options=options))

    def resume(self, *, options: Optional[RequestOptions] = None) -> "Session":
        """Brings a stopped session back on a fresh machine, as it was."""
        return self._set(self._c.sessions.resume(self.id, options=options))

    def delete(self, *, options: Optional[RequestOptions] = None) -> "Session":
        """Ends the session for good: what it saved, its recording and its logs are deleted now. It cannot be undone."""
        return self._set(self._c.sessions.delete(self.id, options=options))

    def update(
        self,
        keep_alive: Optional[bool] = None,
        user_metadata: Optional[JSON] = None,
        captcha: Optional[str] = None,
        browser: Optional[JSON] = None,
        proxy: Any = NOT_GIVEN,
        block_ads: Optional[bool] = None,
        cookie_banners: Optional[str] = None,
        idle_timeout: Any = NOT_GIVEN,
        timeout: Optional[int] = None,
        rotate_proxy: Optional[bool] = None,
        rotate_urls: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> "Session":
        """Changes the running session, with the argument names ``sessions.create`` has: ``keep_alive``, ``timeout`` (its
        length in seconds from its last start), ``idle_timeout`` (``None`` switches it off), ``user_metadata``, ``proxy``
        (``None`` removes it), ``captcha``, ``browser`` settings, ``block_ads``, ``cookie_banners``, plus
        ``rotate_proxy=True`` (a new proxy IP now) and ``rotate_urls=True`` (the current connect, live and terminal URLs
        stop working and the session gets fresh ones). What is fixed when the session is created raises
        NotUpdatableError."""
        return self._set(
            self._c.sessions.update(
                self.id, keep_alive, user_metadata, captcha, browser, proxy, block_ads, cookie_banners, idle_timeout, timeout, rotate_proxy, rotate_urls, options=options
            )
        )

    def wait_for_human(self, timeout: float = 300, interval: float = 1) -> "Session":
        """Waits until no CAPTCHA is waiting for a person (someone solved it in the live view, or the page moved
        on). ``data["attention"]`` shows the one waiting. Raises CaptchaTimeoutError after ``timeout`` seconds."""
        deadline = time.monotonic() + timeout
        while True:
            self.refresh()
            attention = self.data.get("attention")
            if not attention or self.data.get("status") != "RUNNING":
                return self
            if time.monotonic() > deadline:
                raise CaptchaTimeoutError(408, "captcha_timeout", f"nobody solved the CAPTCHA on {attention.get('url')} in time")
            _sleep(interval)

    def on_captcha(self, handler: Callable[[t.CaptchaChange], Any], interval: float = 2.0, after: int = 0) -> Callable[[], None]:
        """Calls ``handler(change)`` when a CAPTCHA starts waiting for a person (``change["state"]`` is ``"detected"``) and
        when it is gone (``"cleared"``); ``change`` is ``{"state", "kind", "url", "event"}`` (``event`` is the session's
        ``captcha`` event). It polls the session's ``captcha`` events every ``interval`` seconds, starting after event
        number ``after`` (default 0: challenges seen before you subscribed are reported too), and stops by itself when the
        session ends; the function it returns stops it sooner::

            stop = s.on_captcha(lambda change: print(change["state"], change["kind"], change["url"]))
            ...
            stop()

        In the async client ``handler`` may be a coroutine function and runs in the event loop; in the sync client it runs
        on a daemon thread, so it must be a plain function."""
        stop = {"stopped": False}

        def watch() -> None:
            cursor: Any = after
            rounds = 0
            while not stop["stopped"]:
                rounds += 1
                try:
                    page = self.events(types=["captcha"], after=cursor)
                    for event in page.data:
                        if stop["stopped"]:
                            return
                        data: Any = event.get("data") or {}
                        if data.get("state") in ("detected", "cleared") and data.get("kind"):
                            outcome = handler({"state": data["state"], "kind": data["kind"], "url": event.get("url") or "", "event": event})
                    cursor = page.raw.get("nextAfter", cursor)
                    if rounds % 5 == 0:
                        self.refresh()  # stop by itself once the session has ended
                    if self.data.get("status") != "RUNNING":
                        return
                except Exception:  # keep polling: the session may be recovering
                    pass
                _sleep(interval)

        threading.Thread(target=watch, name="boxline-on-captcha", daemon=True).start()
        
        def stop_watching() -> None:
            stop["stopped"] = True
        return stop_watching

    # ----- browser

    def actions(self, actions: Union[ActionItem, Sequence[ActionItem]], timeout_ms: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> List[t.ActionResult]:
        """Runs actions next to the browser in one call, e.g. ``[{"action": "goto", "url": ...}, "click Sign in",
        {"action": "content"}]`` (a bare string is a plain-English step)."""
        return self._c.sessions.actions(self.id, actions, timeout_ms, options=options)

    def _one(self, action: JSON, options: Optional[RequestOptions] = None) -> Any:
        r = (self.actions(action, options=options))[0]
        if not r.get("ok"):
            code = r.get("code") or "action_failed"
            raise make_error(_ACTION_STATUS.get(code, 400), code, r.get("error") or "action failed")
        return r.get("value")

    def step(
        self,
        instruction: str,
        variables: Optional[Dict[str, str]] = None,
        provider: Optional[str] = None,
        model: Optional[str] = None,
        credentials: Optional[Sequence[str]] = None,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.StepResult:
        """Runs one plain-English step ("click Sign in", "type %email% into the email field"). Variable values are
        filled in on the server and never sent to the model. Returns what was done and the Playwright ``code``.

        ``credentials``: credentials usable as placeholders (scope "agent" or "all"): ``%NAME%`` for a secret,
        ``%NAME.username%``, ``%NAME.password%`` and ``%NAME.otp%`` for a password, each only on its own sites and in the
        shell only with ``shell: True``; the result never shows their values. In a session whose profile links a
        password credential, that credential is offered too. In a session with Chrome extensions, credentials need
        ``allow_with_extensions=True`` (VariablesWithExtensionsError otherwise)."""
        body = {"action": "step", "instruction": instruction, "variables": variables, "provider": provider, "model": model, "credentials": as_list(credentials), "allowWithExtensions": allow_with_extensions}
        return self._one(clean(body), options)

    def extract(self, instruction: str, schema: Optional[JSON] = None, provider: Optional[str] = None, model: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.ExtractValue:
        """Structured data from the current page: ``{"data", "model", "usage"}``."""
        return self._one(clean({"action": "extract", "instruction": instruction, "schema": schema, "provider": provider, "model": model}), options)

    def goto(self, url: str, wait_until: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.GotoResult:
        return self._one(clean({"action": "goto", "url": url, "waitUntil": wait_until}), options)

    def click(
        self,
        selector: Optional[str] = None,
        x: Optional[float] = None,
        y: Optional[float] = None,
        button: Optional[str] = None,
        count: Optional[int] = None,
        modifiers: Optional[Sequence[str]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> None:
        """Clicks an element (CSS selector) or a point (``x``, ``y``); ``count=2`` double-clicks, ``button="right"``
        right-clicks, ``modifiers=["Shift"]`` holds keys."""
        self._one(clean({"action": "click", "selector": selector, "x": x, "y": y, "button": button, "count": count, "modifiers": as_list(modifiers)}), options)

    def hover(self, selector: Optional[str] = None, x: Optional[float] = None, y: Optional[float] = None, *, options: Optional[RequestOptions] = None) -> None:
        """Moves the pointer over an element (CSS selector) or to a point."""
        self._one(clean({"action": "hover", "selector": selector, "x": x, "y": y}), options)

    def cursor(self, *, options: Optional[RequestOptions] = None) -> t.Point:
        """Where the pointer is on this tab (where the API last moved it; 0, 0 before any move)."""
        return self._one({"action": "cursor"}, options)

    def fill(self, selector: str, value: str, *, options: Optional[RequestOptions] = None) -> None:
        self._one({"action": "fill", "selector": selector, "value": value}, options)

    def type(self, text: str, selector: Optional[str] = None, delay_ms: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> None:
        """Types text with the keyboard (into ``selector`` if given)."""
        self._one(clean({"action": "type", "text": text, "selector": selector, "delayMs": delay_ms}), options)

    def type_credential(
        self,
        credential: str,
        field: Optional[t.CredentialField] = None,
        selector: Optional[str] = None,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> None:
        """Types a credential's value without it passing through you: ``field`` is ``"username"``, ``"password"`` or
        ``"otp"`` (the current 2FA code, made when it is typed; with ``code_source`` "push" or "url" it waits for a fresh
        one, up to ``codeTimeoutSeconds``, and raises CredentialCodeTimeoutError without one) for a password credential,
        and left out for a secret. A credential with sites (every password) goes only into the field ``selector`` names, whose own frame must be on
        one of its sites, checked right before writing; one without sites may be typed where the focus is. The value is
        never in the reply or the session's log. Needs scope "agent" or "all" (CredentialNotAllowedError for "shell");
        the first use per session is audited. In a session with Chrome extensions it needs
        ``allow_with_extensions=True``."""
        body = {"action": "type", "credential": credential, "field": field, "selector": selector, "allowWithExtensions": allow_with_extensions}
        self._one(clean(body), options)

    def login(
        self,
        credential: Optional[str] = None,
        url: Optional[str] = None,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.LoginValue:
        """Signs the browser in with a password credential in one call (default: the one the session's profile links;
        ``url`` is the sign-in page, on one of the credential's sites, default the first). A short agent run does it (at
        most 15 steps, browser tools only, only that credential and its sites; the project's default model, counted like
        an agent run), and a credential with ``code_source`` "push" or "url" waits for its code or sign-in link, which the
        run never sees. Returns the page it ends on (no query or fragment) and the run's id. Raises
        CredentialLoginFailedError (its ``run_id`` is the run; CredentialLoginTimeoutError when it ran out of time and was
        canceled), CredentialCodeTimeoutError (no code in time) or
        CredentialLinkWrongSiteError; needs the plan's ``loginDetails`` (FeatureNotInPlanError) and a session with a
        browser. It runs alone as one action."""
        r = (self.actions(clean({"action": "login", "credential": credential, "url": url, "allowWithExtensions": allow_with_extensions}), options=options))[0]
        if r.get("ok"):
            return r.get("value")
        code = r.get("code") or "credential_login_failed"
        err = make_error(_ACTION_STATUS.get(code, 400), code, r.get("error") or "could not sign in")
        if isinstance(err, CredentialLoginFailedError):
            err.run_id = r.get("runId")
        raise err

    def press(self, key: str, *, options: Optional[RequestOptions] = None) -> None:
        self._one({"action": "press", "key": key}, options)

    def scroll(
        self,
        delta_y: float,
        x: Optional[float] = None,
        y: Optional[float] = None,
        delta_x: Optional[float] = None,
        modifiers: Optional[Sequence[str]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> None:
        """Turns the wheel by ``delta_y`` pixels (and ``delta_x``), over ``x``/``y`` when given."""
        self._one(clean({"action": "scroll", "deltaY": delta_y, "deltaX": delta_x, "x": x, "y": y, "modifiers": as_list(modifiers)}), options)

    def wait(self, selector: Optional[str] = None, ms: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> None:
        """Waits for a selector, or a number of milliseconds."""
        self._one(clean({"action": "wait", "selector": selector, "ms": ms}), options)

    def select(self, selector: str, option: str, *, options: Optional[RequestOptions] = None) -> None:
        """Picks an option of a select element by its label or value."""
        self._one({"action": "select", "selector": selector, "option": option}, options)

    def elements(self, *, options: Optional[RequestOptions] = None) -> t.PageElements:
        """The page as a model sees it: title, URL, visible text and numbered interactive elements."""
        return self._one({"action": "elements"}, options)

    def evaluate(self, expression: str, *, options: Optional[RequestOptions] = None) -> Any:
        return self._one({"action": "evaluate", "expression": expression}, options)

    def content(self, format: str = "markdown", *, options: Optional[RequestOptions] = None) -> t.PageContent:
        """The current page as markdown, html or text: ``{"url", "title", "content"}``."""
        return self._one({"action": "content", "format": format}, options)

    def screenshot(
        self,
        full_page: bool = False,
        format: str = "png",
        quality: Optional[int] = None,
        max_width: Optional[int] = None,
        cursor: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> bytes:
        """A screenshot of the current tab: PNG or JPEG bytes. ``max_width`` scales it down; ``cursor=True`` draws the
        pointer."""
        v = self._one(clean({"action": "screenshot", "fullPage": full_page, "format": format, "quality": quality, "maxWidth": max_width, "cursor": cursor}), options)
        return base64.b64decode(v["data"])

    def computer(
        self,
        action: JSON,
        max_width: Optional[int] = None,
        screenshot: Optional[bool] = None,
        format: Optional[str] = None,
        quality: Optional[int] = None,
        cursor: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.ComputerResult:
        """Runs ONE computer-use action as the model's tool gave it and returns the screen after it (see
        ``Sessions.computer``)."""
        return self._c.sessions.computer(self.id, action, max_width, screenshot, format, quality, cursor, options=options)

    def upload(self, selector: str, path: str, *, options: Optional[RequestOptions] = None) -> None:
        """Sets a file input to a file in the workspace (e.g. one written with ``files.write``)."""
        self._one({"action": "upload", "selector": selector, "path": path}, options)

    def tabs(self, *, options: Optional[RequestOptions] = None) -> t.TabList:
        return self._one({"action": "tabs"}, options)

    def new_tab(self, url: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> JSON:
        return self._one(clean({"action": "newTab", "url": url}), options)

    def switch_tab(self, index: int, *, options: Optional[RequestOptions] = None) -> None:
        self._one({"action": "switchTab", "index": index}, options)

    def close_tab(self, index: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> None:
        self._one(clean({"action": "closeTab", "index": index}), options)

    def back(self, *, options: Optional[RequestOptions] = None) -> JSON:
        return self._one({"action": "back"}, options)

    def forward(self, *, options: Optional[RequestOptions] = None) -> JSON:
        return self._one({"action": "forward"}, options)

    def reload(self, *, options: Optional[RequestOptions] = None) -> JSON:
        return self._one({"action": "reload"}, options)

    def export_cookies(self, path: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.CookieFile:
        """Writes the browser's cookies as a Netscape cookie file in the workspace (for curl -b / wget)."""
        return self._c.sessions.export_cookies(self.id, path, options=options)

    # ----- shell

    def exec(
        self,
        command: str,
        timeout_ms: Optional[int] = None,
        cwd: Optional[str] = None,
        env: Optional[Dict[str, str]] = None,
        shell: Optional[Union[str, bool]] = None,
        credentials: Optional[Sequence[str]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.ExecResult:
        """Runs a command (persistent bash by default: cd/export survive). Returns stdout, stderr, exitCode…
        ``shell=False`` runs it in a fresh process; ``credentials`` are credentials for this command only."""
        return self._c.sessions.exec(self.id, command, timeout_ms, cwd, env, shell, credentials, options=options)

    def exec_stream(
        self,
        command: str,
        timeout_ms: Optional[int] = None,
        cwd: Optional[str] = None,
        env: Optional[Dict[str, str]] = None,
        shell: Optional[Union[str, bool]] = None,
        credentials: Optional[Sequence[str]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> ExecStream:
        """Runs a command and streams its output while it runs::

            proc = s.exec_stream("npm install")
            with proc:
                for stream, text in proc:
                    print(text, end="")
            print(proc.result["exitCode"])
        """
        return self._c.sessions.exec_stream(self.id, command, timeout_ms, cwd, env, shell, credentials, options=options)

    def run_script(
        self,
        code: str,
        env: Optional[Dict[str, str]] = None,
        timeout_ms: Optional[int] = None,
        ai: Optional[Dict[str, str]] = None,
        credentials: Optional[Sequence[str]] = None,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> ExecStream:
        """Runs Playwright (JavaScript) code inside the session, streaming its output (see ``Sessions.run_script``)."""
        return self._c.sessions.run_script(self.id, code, env, timeout_ms, ai, credentials, allow_with_extensions, options=options)

    def restart_shell(self, name: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> None:
        self._c.sessions.restart_shell(self.id, name, options=options)

    # ----- logs and recording

    def events(self, types: Optional[Sequence[str]] = None, after: Optional[Union[int, str]] = None, limit: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.SessionEvent]:
        """Console, network, navigation, error, lifecycle, action, exec and captcha events (oldest first)."""
        return self._c.sessions.events(self.id, types, after, limit, options=options)

    def stream_events(self, after: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> Iterator[t.SessionEvent]:
        """Events as they happen (the backlog after ``after`` first), until you stop iterating."""
        return self._c.sessions.stream_events(self.id, after, options=options)

    def pages(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.VisitedPage]:
        """Pages visited in this session."""
        return self._c.sessions.pages(self.id, limit, after, options=options)

    def recording(self, *, options: Optional[RequestOptions] = None) -> t.Recording:
        return self._c.sessions.recording(self.id, options=options)

    def recording_frame(self, index: int, *, options: Optional[RequestOptions] = None) -> bytes:
        """One replay frame as JPEG bytes."""
        return self._c.sessions.recording_frame(self.id, index, options=options)


class Mouse:
    """The mouse, in viewport CSS pixels (the session's viewport, 1280×720 by default). Straight lines only: ``steps``
    spreads a move over that many evenly spaced points. It acts on the page, never on the machine's desktop."""

    def __init__(self, session: Session) -> None:
        self._s = session

    def move(self, x: float, y: float, steps: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> t.Point:
        return self._s._one(clean({"action": "move", "x": x, "y": y, "steps": steps}), options)

    def move_by(self, dx: float, dy: float, steps: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> t.Point:
        """Moves by ``dx``/``dy`` from where the pointer is."""
        return self._s._one(clean({"action": "move", "dx": dx, "dy": dy, "steps": steps}), options)

    def click(self, x: float, y: float, button: Optional[str] = None, count: Optional[int] = None, modifiers: Optional[Sequence[str]] = None, *, options: Optional[RequestOptions] = None) -> None:
        self._s._one(clean({"action": "click", "x": x, "y": y, "button": button, "count": count, "modifiers": as_list(modifiers)}), options)

    def down(self, button: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> None:
        self._s._one(clean({"action": "mouse_down", "button": button}), options)

    def up(self, button: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> None:
        self._s._one(clean({"action": "mouse_up", "button": button}), options)

    def drag(
        self,
        start: Optional[PointLike] = None,
        end: Optional[PointLike] = None,
        *,
        path: Optional[Sequence[PointLike]] = None,
        steps: Optional[int] = None,
        button: Optional[str] = None,
        modifiers: Optional[Sequence[str]] = None,
        options: Optional[RequestOptions] = None,
    ) -> JSON:
        """Presses at ``start``, moves to ``end`` (in ``steps`` points, default 10) and releases; each end is ``(x, y)``,
        ``{"x", "y"}`` or a selector. Or ``path=[(x, y), …]`` (2–200 points) to follow. Returns ``{"from", "to"}``."""
        body: JSON = {"action": "drag", **clean({"steps": steps, "button": button, "modifiers": as_list(modifiers)})}
        if path is not None:
            body["path"] = [_point(p) for p in path]
        else:
            if start is None or end is None:
                raise ValueError("drag needs start and end, or path")
            body["from"], body["to"] = _point(start), _point(end)
        return self._s._one(body, options)


class Keyboard:
    """The keyboard. Key names are Playwright's (Enter, Tab, ArrowLeft, Control, Shift, Meta…); ctrl, cmd and Return
    work too."""

    def __init__(self, session: Session) -> None:
        self._s = session

    def key(self, keys: Union[str, Sequence[str]], hold_ms: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> None:
        """A combination held together, ``"Control+A"`` or ``["Control", "A"]``; several separated by spaces run one after
        the other."""
        self._s._one(clean({"action": "key", "keys": keys if isinstance(keys, str) else list(keys), "holdMs": hold_ms}), options)

    def type(self, text: str, delay_ms: Optional[int] = None, *, options: Optional[RequestOptions] = None) -> None:
        self._s._one(clean({"action": "type", "text": text, "delayMs": delay_ms}), options)

    def press(self, key: str, *, options: Optional[RequestOptions] = None) -> None:
        self._s._one({"action": "press", "key": key}, options)


class Files:
    """Files in the session's workspace (shared by the shell and the browser's downloads folder). ``list``, ``read`` and
    ``archive`` also work on a stopped session (read-only, no machine started); ``write``, ``delete`` and ``wait_for``
    need it running."""

    def __init__(self, session: Session) -> None:
        self._s = session

    def list(self, path: str = ".", *, options: Optional[RequestOptions] = None) -> List[t.FileEntry]:
        return self._s._c.sessions.files.list(self._s.id, path, options=options)

    def read(self, path: str, *, options: Optional[RequestOptions] = None) -> bytes:
        return self._s._c.sessions.files.read(self._s.id, path, options=options)

    def archive(self, path: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> bytes:
        """A folder (default: the whole workspace) and everything in it as one ``.tar.gz`` (the bytes)."""
        return self._s._c.sessions.files.archive(self._s.id, path, options=options)

    def read_text(self, path: str, encoding: str = "utf-8", *, options: Optional[RequestOptions] = None) -> str:
        return self._s._c.sessions.files.read_text(self._s.id, path, encoding, options=options)

    def write(self, path: str, data: Union[str, bytes], *, options: Optional[RequestOptions] = None) -> t.FileRef:
        return self._s._c.sessions.files.write(self._s.id, path, data, options=options)

    def delete(self, path: str, *, options: Optional[RequestOptions] = None) -> None:
        self._s._c.sessions.files.delete(self._s.id, path, options=options)

    def wait_for(self, pattern: str, timeout_ms: int = 30_000, *, options: Optional[RequestOptions] = None) -> t.FileRef:
        """Waits for a file matching a glob (e.g. ``downloads/*.csv``) that has finished writing."""
        return self._s._c.sessions.files.wait_for(self._s.id, pattern, timeout_ms, options=options)


# ---------------------------------------------------------------- profiles


class Profiles:
    """Browser profiles: cookies and local storage to start sessions with (``profile=id, persist_profile=True`` fills one)."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def create(
        self,
        name: Optional[str] = None,
        *,
        from_session: Optional[str] = None,
        attach: Optional[bool] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.Profile:
        """A new profile: empty, or with ``from_session`` holding that working session's current cookies and site
        storage (sign in there first, e.g. in its live view). ``attach=True`` also makes the session save to it from now
        on (at its checkpoints and when it ends); a session that already has a profile refuses that (409
        ``conflict``). 413 ``profile_too_large`` over 16 MB; PlanLimitError (402) past the plan's ``maxProfiles`` or
        ``maxProfileBytes``."""
        body = clean({"name": name, "fromSession": from_session, "attach": attach})
        return self._c._json("POST", "/v1/profiles", json=body, options=options)

    def get(self, profile_id: str, *, options: Optional[RequestOptions] = None) -> t.Profile:
        return self._c._json("GET", f"/v1/profiles/{seg(profile_id)}", options=options)

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.Profile]:
        """Newest first; the first page's ``total`` counts them all."""
        return self._c._list("/v1/profiles", {"limit": limit, "after": after}, lambda c: c, options)

    def update(
        self,
        profile_id: str,
        name: Optional[str] = None,
        credential: Any = NOT_GIVEN,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.Profile:
        """Changes the name and/or the password credential the profile signs in with (at least one).
        ``credential="SHOP"`` links a password credential (see ``credentials``), so sessions with this profile, and agent
        runs, task runs and steps in them, get it as if it were listed in their ``credentials`` and the AI can sign in
        again when the cookies have expired; ``credential=None`` unlinks it. NotFoundError (404
        ``credential_not_found``) for a name the project does not have, a 400 BoxlineError for a secret (only passwords
        sign in), FeatureNotInPlanError (402) without the plan's ``loginDetails``."""
        body = clean({"name": name})
        if credential is not NOT_GIVEN:
            body["credential"] = credential
        return self._c._json("PATCH", f"/v1/profiles/{seg(profile_id)}", json=body, options=options)

    def delete(self, profile_id: str, *, options: Optional[RequestOptions] = None) -> None:
        self._c._json("DELETE", f"/v1/profiles/{seg(profile_id)}", options=options)


# ---------------------------------------------------------------- credentials


class Credentials:
    """Credentials: write-only website passwords (with an optional 2FA key) and secrets. The AI uses them as
    placeholders (``%NAME%``, ``%SHOP.password%``) with ``credentials=`` on agent runs, steps, scripts, tasks and
    ``Session.type_credential``; shells get them as environment variables (``credentials=`` on ``sessions.create`` and
    ``exec``), depending on each credential's ``scope``. A value is never returned, logged or shown; every change and
    use is audited."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.Credential]:
        """The project's credentials, in name order, without their values."""
        return self._c._list("/v1/credentials", {"limit": limit, "after": after}, lambda c: c, options)

    @overload
    def create(
        self,
        name: str,
        type: Literal["password"],
        *,
        origins: Sequence[str],
        username: str,
        password: str,
        code_source: Optional[t.CredentialCodeSource] = None,
        totp_secret: Optional[str] = None,
        code_url: Optional[str] = None,
        code_timeout_seconds: Optional[int] = None,
        description: Optional[str] = None,
        shell: Optional[bool] = None,
        scope: Optional[t.CredentialScope] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.PasswordCredentialWritten: ...

    @overload
    def create(
        self,
        name: str,
        type: Literal["secret"],
        *,
        value: str,
        origins: Optional[Sequence[str]] = None,
        description: Optional[str] = None,
        shell: Optional[bool] = None,
        scope: Optional[t.CredentialScope] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.SecretCredential: ...

    def create(
        self,
        name: str,
        type: t.CredentialType,
        *,
        origins: Optional[Sequence[str]] = None,
        username: Optional[str] = None,
        password: Optional[str] = None,
        code_source: Optional[t.CredentialCodeSource] = None,
        totp_secret: Optional[str] = None,
        code_url: Optional[str] = None,
        code_timeout_seconds: Optional[int] = None,
        value: Optional[str] = None,
        description: Optional[str] = None,
        shell: Optional[bool] = None,
        scope: Optional[t.CredentialScope] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.CredentialWritten:
        """Stores a credential, sealed; the answer never has a value.

        ``name``: an environment variable name in capitals (``[A-Z_][A-Z0-9_]*``, at most 64; not PATH, HOME or
        BOXLINE_*/SANDBOXD_*/BASH_*), one per project. ``type="password"`` takes ``origins`` (1 to 20 sites, required),
        ``username``, ``password`` and optionally where its 2FA codes come from: ``code_source="totp"`` with
        ``totp_secret`` (the site's 2FA setup key, or an ``otpauth://totp/`` link; ``totp_secret`` alone means "totp"),
        ``"push"`` (send each code or sign-in link with ``push_code``) or ``"url"`` with ``code_url`` (a public HTTPS
        endpoint the platform asks with a signed POST; the answer then has ``codeUrlSecret``, shown this once);
        ``code_timeout_seconds`` (5 to 900, default 300) is how long a "push" or "url" wait lasts (needs the plan's
        ``loginDetails``: FeatureNotInPlanError; 400 ``code_url_not_allowed`` for a ``code_url`` that is not a public
        HTTPS address); ``type="secret"`` takes ``value`` (1 to 8000 characters) and optionally ``origins``. ``scope``: ``"agent"`` (default: only the AI, as placeholders),
        ``"shell"`` (only as environment variables in shells and commands) or ``"all"``. ``shell=True`` lets the AI use
        it in bash commands (and so export it). CredentialExistsError for a name the project has (use ``update``),
        PlanLimitError beyond the plan's ``maxCredentials``. Not retried (the API takes no Idempotency-Key here)."""
        body = clean(
            {
                "name": name,
                "type": type,
                "origins": as_list(origins),
                "username": username,
                "password": password,
                "codeSource": code_source,
                "totpSecret": totp_secret,
                "codeUrl": code_url,
                "codeTimeoutSeconds": code_timeout_seconds,
                "value": value,
                "description": description,
                "shell": shell,
                "scope": scope,
            }
        )
        return self._c._json("POST", "/v1/credentials", json=body, options=options)

    def get(self, name: str, *, options: Optional[RequestOptions] = None) -> t.Credential:
        return self._c._json("GET", f"/v1/credentials/{seg(name)}", options=options)

    def update(
        self,
        name: str,
        *,
        origins: Any = NOT_GIVEN,
        username: Optional[str] = None,
        password: Optional[str] = None,
        code_source: Any = NOT_GIVEN,
        totp_secret: Any = NOT_GIVEN,
        code_url: Optional[str] = None,
        code_timeout_seconds: Optional[int] = None,
        value: Optional[str] = None,
        description: Any = NOT_GIVEN,
        shell: Optional[bool] = None,
        scope: Optional[t.CredentialScope] = None,
        rotate_code_url_secret: Optional[bool] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.CredentialWritten:
        """Changes the fields you pass (a password's ``origins``, ``username``, ``password``, ``code_source``,
        ``totp_secret``, ``code_url``, ``code_timeout_seconds``; a secret's ``value`` and ``origins``; for both
        ``description``, ``shell`` and ``scope``); the type cannot change (delete it and create it again).
        ``description=None`` clears it, ``totp_secret=None`` or ``code_source=None`` removes 2FA, ``origins=None`` allows
        any site (a secret only). A new site, or a ``scope``/``shell`` that makes an AI-only credential readable by
        shells, needs the sensitive values again in the same call (a secret's ``value``; a password's ``password``, and
        ``totp_secret`` when it has 2FA), else a 400 ``invalid_request``; so does a change of ``code_source`` (removing
        2FA included) or ``code_url`` (the ``password`` again). A 409 ``conflict`` when the sites, scope, ``shell``,
        ``code_source`` or ``code_url`` changed meanwhile (send it again). A new ``code_url`` answers with a new
        ``codeUrlSecret``, shown once, and so does ``rotate_code_url_secret=True`` (any time, for a password with
        ``code_source="url"``: requests to ``code_url`` are signed with it from now on, check them with
        ``verify_webhook``; the old one stops at once). A running agent run keeps the values it started with; a session
        that exports the credential gets the new ones on its next machine (resume, recovery)."""
        body = clean(
            {
                "username": username,
                "password": password,
                "codeUrl": code_url,
                "codeTimeoutSeconds": code_timeout_seconds,
                "value": value,
                "shell": shell,
                "scope": scope,
                "rotateCodeUrlSecret": rotate_code_url_secret,
            }
        )
        if description is not NOT_GIVEN:
            body["description"] = description
        if code_source is not NOT_GIVEN:
            body["codeSource"] = code_source
        if totp_secret is not NOT_GIVEN:
            body["totpSecret"] = totp_secret
        if origins is not NOT_GIVEN:
            body["origins"] = None if origins is None else list(origins)
        return self._c._json("PATCH", f"/v1/credentials/{seg(name)}", json=body, options=options)

    def delete(self, name: str, *, options: Optional[RequestOptions] = None) -> None:
        """Deletes it; profiles that link it are unlinked, and sessions that exported it no longer get it on their next
        machine."""
        self._c._json("DELETE", f"/v1/credentials/{seg(name)}", options=options)

    def push_code(
        self,
        name: str,
        code: Optional[str] = None,
        link: Optional[str] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.CredentialCodeAccepted:
        """For a password with ``code_source="push"``: sends the code (``code=``) or the sign-in link (``link=``), exactly
        one of them, that the site emailed or texted, for a run, action or ``boxline-otp`` that waits for it (the webhook
        ``credential.code_needed`` says when). It is kept sealed for up to 10 minutes and used once, by a wait that began
        before it arrived. A link must be on one of the credential's sites (400 ``credential_link_wrong_site``). 400
        ``invalid_request`` for a credential whose source is not "push"; NotFoundError for one the project does not
        have. Not retried (a second push is a second code). The value is never logged or returned."""
        if (code is None) == (link is None):
            raise ValueError("push_code takes exactly one of code= and link=")
        body = {"code": code} if code is not None else {"link": link}
        return self._c._json("POST", f"/v1/credentials/{seg(name)}/codes", json=body, options=options)

    def audit(self, name: Optional[str] = None, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.CredentialAuditEntry]:
        """Changes to credentials, each use (once per session, command, run, script, task run, typed field or 2FA code)
        and pushed codes, newest first; ``name`` picks one credential. Never values."""
        return self._c._list("/v1/credentials/audit", {"name": name, "limit": limit, "after": after}, lambda e: e, options)


# ---------------------------------------------------------------- crawl


class Crawl:
    """Crawls: follow links from a start URL in the background (robots.txt respected); poll with get() or wait()."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def start(
        self,
        url: str,
        max_pages: Optional[int] = None,
        max_depth: Optional[int] = None,
        same_host: Optional[bool] = None,
        include: Optional[Sequence[str]] = None,
        exclude: Optional[Sequence[str]] = None,
        format: Optional[str] = None,
        wait_until: Optional[str] = None,
        delay_ms: Optional[int] = None,
        timeout_ms: Optional[int] = None,
        proxy: Optional[Proxy] = None,
        browser: Optional[Union[bool, JSON]] = None,
        block_ads: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.CrawlJob:
        """Starts a crawl (an Idempotency-Key is sent, so a retry never starts a second one)."""
        body = clean({"url": url, "maxPages": max_pages, "maxDepth": max_depth, "sameHost": same_host, "include": as_list(include), "exclude": as_list(exclude),
                      "format": format, "waitUntil": wait_until, "delayMs": delay_ms, "timeoutMs": timeout_ms, "proxy": proxy, "browser": browser, "blockAds": block_ads})
        return self._c._json("POST", "/v1/crawls", json=body, options=options)

    def get(self, crawl_id: str, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.CrawlJob:
        """The job and one page of its pages (``limit=0`` for the job only); ``next`` is the cursor of the following pages."""
        return self._c._json("GET", f"/v1/crawls/{seg(crawl_id)}", params={"limit": limit, "after": after}, options=options)

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.CrawlJob]:
        """Jobs, newest first (without their pages)."""
        return self._c._list("/v1/crawls", {"limit": limit, "after": after}, lambda j: j, options)

    def cancel(self, crawl_id: str, *, options: Optional[RequestOptions] = None) -> t.CrawlJob:
        return self._c._json("POST", f"/v1/crawls/{seg(crawl_id)}/cancel", options=options)

    def pages(self, crawl_id: str, limit: int = 100, *, options: Optional[RequestOptions] = None) -> Iterator[t.CrawlPage]:
        """Every page crawled so far, in index order (``limit`` pages per request)."""
        after: Optional[str] = None
        while True:
            job = self.get(crawl_id, limit=limit, after=after, options=options)
            for page in job["data"]:
                yield page
            after = job.get("next")
            if not after:
                return

    def wait(self, crawl_id: str, poll: float = 1.0, timeout: float = 1800.0, *, options: Optional[RequestOptions] = None) -> t.CrawlJob:
        """Waits for the crawl to finish and returns the job with every page in ``data``."""
        deadline = time.monotonic() + timeout
        job = self.get(crawl_id, limit=0, options=options)
        while job["status"] == "running":
            if time.monotonic() > deadline:
                raise BoxlineTimeoutError("the crawl did not finish in time")
            _sleep(poll)
            job = self.get(crawl_id, limit=0, options=options)
        job["data"] = [p for p in self.pages(crawl_id, options=options)]
        job["next"] = None
        return job


# ---------------------------------------------------------------- webhooks


class Webhooks:
    """Webhook endpoints: signed HTTPS callbacks when something finishes or needs a person. Verify each delivery with
    ``verify_webhook(raw_body, header, secret)`` and drop event ids you have handled already."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def create(self, url: str, events: Sequence[str], description: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.NewWebhookEndpoint:
        """A new endpoint (public HTTPS only); ``secret`` ("whsec_…") is in this response only. ``events``: event
        types, or ``["*"]`` for all of them (those added later too)."""
        return self._c._json("POST", "/v1/webhooks", json=clean({"url": url, "events": list(events), "description": description}), options=options)

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.WebhookEndpoint]:
        """The project's endpoints, oldest first (never their secrets)."""
        return self._c._list("/v1/webhooks", {"limit": limit, "after": after}, lambda w: w, options)

    def get(self, webhook_id: str, *, options: Optional[RequestOptions] = None) -> t.WebhookEndpoint:
        return self._c._json("GET", f"/v1/webhooks/{seg(webhook_id)}", options=options)

    @overload
    def update(
        self,
        webhook_id: str,
        url: Optional[str] = None,
        events: Optional[Sequence[str]] = None,
        enabled: Optional[bool] = None,
        description: Any = NOT_GIVEN,
        *,
        rotate_secret: Literal[True],
        options: Optional[RequestOptions] = None,
    ) -> t.NewWebhookEndpoint: ...

    @overload
    def update(
        self,
        webhook_id: str,
        url: Optional[str] = None,
        events: Optional[Sequence[str]] = None,
        enabled: Optional[bool] = None,
        description: Any = NOT_GIVEN,
        *,
        rotate_secret: Optional[bool] = None,
        options: Optional[RequestOptions] = None,
    ) -> t.WebhookEndpoint: ...

    def update(
        self,
        webhook_id: str,
        url: Optional[str] = None,
        events: Optional[Sequence[str]] = None,
        enabled: Optional[bool] = None,
        description: Any = NOT_GIVEN,
        *,
        rotate_secret: Optional[bool] = None,
        options: Optional[RequestOptions] = None,
    ) -> Any:
        """Changes the URL, events or description (``None`` clears it), or switches it on or off (``enabled=True`` also
        forgets its failures). ``rotate_secret=True`` makes a new signing secret: the answer then has it as ``secret``
        (shown this once), and the old one keeps signing for 24 hours (a second v1)."""
        body = clean({"url": url, "events": as_list(events), "enabled": enabled, "rotateSecret": rotate_secret})
        if description is not NOT_GIVEN:
            body["description"] = description
        return self._c._json("PATCH", f"/v1/webhooks/{seg(webhook_id)}", json=body, options=options)

    def delete(self, webhook_id: str, *, options: Optional[RequestOptions] = None) -> None:
        """Deletes the endpoint with its queue and delivery log."""
        self._c._json("DELETE", f"/v1/webhooks/{seg(webhook_id)}", options=options)

    def test(self, webhook_id: str, type: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.WebhookDelivery:
        """Sends a ``webhook.test`` event to this endpoint now, or with ``type`` a made-up sample of that event type
        (marked ``test: True``); one attempt, waits up to 12 s for the answer."""
        body = {"type": type} if type else None
        return self._c._json("POST", f"/v1/webhooks/{seg(webhook_id)}/test", json=body, options=options)

    def event_types(self, *, options: Optional[RequestOptions] = None) -> t.WebhookEventTypeList:
        """Every event type an endpoint can subscribe to, with its group and description (subscribe to ``"*"`` for
        all)."""
        return self._c._json("GET", "/v1/webhooks/event-types", options=options)

    def deliveries(
        self,
        webhook_id: str,
        status: Optional[str] = None,
        limit: Optional[int] = None,
        after: Optional[str] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> Pager[t.WebhookDelivery]:
        """The endpoint's deliveries, newest first, each with its attempt ``history``; ``status``: pending, delivered or
        failed."""
        return self._c._list(f"/v1/webhooks/{seg(webhook_id)}/deliveries", {"status": status, "limit": limit, "after": after}, lambda d: d, options)

    def retry_delivery(self, webhook_id: str, delivery_id: str, *, options: Optional[RequestOptions] = None) -> t.WebhookDelivery:
        """Sends a finished delivery again now, with the same event id and body (409 invalid_state while it is still
        queued, PayloadExpiredError after 7 days, WebhookDisabledError while the endpoint is switched off)."""
        return self._c._json("POST", f"/v1/webhooks/{seg(webhook_id)}/deliveries/{seg(delivery_id)}/retry", options=options)


# ---------------------------------------------------------------- tasks

#: The task-run statuses of a run that has not finished (queued: a scheduled run waiting for its turn).
_TASK_RUN_OPEN = ["queued", "running", "paused"]


class Tasks:
    """Tasks: saved agent runs (an instruction with ``%name%`` variables, an optional output schema, the ``session`` each
    run starts with, credentials and a model), run by hand or on a schedule. Every run is an agent run tagged with the
    task. Needs the plan's ``agentRuns``; the plan limits tasks and schedules switched on (PlanLimitError)."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def create(
        self,
        name: str,
        instruction: str,
        variables: Optional[Sequence[t.TaskVariable]] = None,
        output: Optional[t.OutputSchema] = None,
        session: Optional[t.SessionSpec] = None,
        model: Optional[Dict[str, str]] = None,
        max_steps: Any = NOT_GIVEN,
        notify_on_failure: Optional[str] = None,
        schedule: Optional[JSON] = None,
        credentials: Optional[Sequence[str]] = None,
        max_cost_usd: Optional[float] = None,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.Task:
        """Saves a task (an Idempotency-Key is sent, so a retry never saves it twice).

        ``instruction`` has ``%name%`` where a variable goes. ``variables``: up to 50 ``{"name", "default", "description"}``,
        or ``{"name", "secret": True, "origins", "shell"}`` for a value that is never stored (it comes with every run,
        and the model sees only ``%name%``). ``output``: a JSON Schema every run's answer must match (see
        ``agent.run``). ``session``: the settings of each run's own session, a ``SessionSpec`` with the API's names, as
        ``sessions.create`` takes them (``{"proxy": {"type": "residential", "country": "GB"}, "blockAds": True,
        "browser": {"locale": "en-GB"}, "profile": {"id": "prof_…"}, "timeout": 900}``); a task can be shell only
        (``{"browser": False, "shell": True}``), and ``env`` is sealed and read back as names only. ``model``:
        ``{"provider", "model"}`` from ``agent.models()``. ``max_steps``: 1-1000 (default 30 when not passed);
        ``max_steps=None`` means no step limit. ``max_cost_usd``: each run's money budget (0.01-100 USD, as on
        ``agent.run``). ``allow_with_extensions=True``: needed for a task with secret variables or credentials and a
        session with extensions. ``schedule``: ``{"cron": "0 9 * * MON-FRI", "timezone": "Europe/London", "variables":
        {...}, "enabled": True}``: at most every 5 minutes, on the plan's ``schedules`` (PlanLimitError beyond).
        ``credentials``: credential names (scope "agent" or "all") each run gets as placeholders, as on ``agent.run``; a
        scheduled task may use them (secret variables cannot be scheduled)."""
        body = clean(
            {
                "name": name,
                "instruction": instruction,
                "variables": list(variables) if variables is not None else None,
                "output": output,
                "session": session,
                "allowWithExtensions": allow_with_extensions,
                "model": model,
                "notifyOnFailure": notify_on_failure,
                "schedule": schedule,
                "credentials": list(credentials) if credentials is not None else None,
                "maxCostUsd": max_cost_usd,
            }
        )
        if max_steps is not NOT_GIVEN:
            body["maxSteps"] = max_steps  # None: no step limit
        return self._c._json("POST", "/v1/tasks", json=body, options=options)

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.Task]:
        """The project's tasks, newest first."""
        return self._c._list("/v1/tasks", {"limit": limit, "after": after}, lambda x: x, options)

    def get(self, task_id: str, *, options: Optional[RequestOptions] = None) -> t.Task:
        return self._c._json("GET", f"/v1/tasks/{seg(task_id)}", options=options)

    def update(
        self,
        task_id: str,
        name: Optional[str] = None,
        instruction: Optional[str] = None,
        variables: Optional[Sequence[t.TaskVariable]] = None,
        output: Any = NOT_GIVEN,
        session: Any = NOT_GIVEN,
        model: Any = NOT_GIVEN,
        max_steps: Any = NOT_GIVEN,
        notify_on_failure: Any = NOT_GIVEN,
        schedule: Any = NOT_GIVEN,
        credentials: Any = NOT_GIVEN,
        max_cost_usd: Any = NOT_GIVEN,
        allow_with_extensions: Optional[bool] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.Task:
        """Changes the fields you pass; ``None`` removes ``output``, ``session`` (the whole new ``SessionSpec``, as on
        ``create``), ``model``, ``max_cost_usd``, ``notify_on_failure``, ``schedule`` or ``credentials`` (the whole new
        list of credential names); ``max_steps=None`` means no step limit.
        ``schedule`` fields are merged into the current schedule (``schedule={"enabled": False}`` pauses it); switching it
        on, or changing cron or timezone, counts from now."""
        body = clean({"name": name, "instruction": instruction, "variables": list(variables) if variables is not None else None, "allowWithExtensions": allow_with_extensions})
        for key, value in (
            ("output", output),
            ("session", session),
            ("model", model),
            ("maxSteps", max_steps),
            ("notifyOnFailure", notify_on_failure),
            ("schedule", schedule),
            ("credentials", list(credentials) if credentials is not NOT_GIVEN and credentials is not None else credentials),
            ("maxCostUsd", max_cost_usd),
        ):
            if value is not NOT_GIVEN:
                body[key] = value
        return self._c._json("PATCH", f"/v1/tasks/{seg(task_id)}", json=body, options=options)

    def delete(self, task_id: str, *, options: Optional[RequestOptions] = None) -> None:
        """Deletes the task with its run history (its agent runs stay, and runs in progress go on)."""
        self._c._json("DELETE", f"/v1/tasks/{seg(task_id)}", options=options)

    def run(
        self,
        task_id: str,
        variables: Optional[Dict[str, Union[str, int, float, bool]]] = None,
        session_id: Optional[str] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.TaskRun:
        """Runs the task now and returns its task run (status running) right away; ``wait_for_run`` waits for the result.
        Plain values are written into the instruction; secret ones must come with every run and go in as agent
        variables (the model sees only ``%name%``). MissingVariablesError when a variable without a default has no
        value. ``session_id``: work in that session (its own settings apply; the task's ``session`` does not). Counts as an agent run (rate, plan, spend
        cap). An Idempotency-Key is sent, so a retry never starts a second run."""
        body = clean({"variables": variables, "sessionId": session_id})
        return self._c._json("POST", f"/v1/tasks/{seg(task_id)}/runs", json=body, options=options)

    def runs(
        self,
        task_id: str,
        status: Optional[Union[str, Sequence[str]]] = None,
        limit: Optional[int] = None,
        after: Optional[str] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> Pager[t.TaskRun]:
        """The task's runs, newest first: by hand, on the schedule, and skipped or missed times (kept 30 days).
        ``status``: one or more of queued, running, paused, completed, failed, canceled, skipped, missed."""
        return self._c._list(f"/v1/tasks/{seg(task_id)}/runs", {"status": status, "limit": limit, "after": after}, lambda r: r, options)

    def wait_for_run(
        self,
        task_id: Union[str, t.TaskRun],
        task_run_id: Optional[str] = None,
        poll: float = 1.0,
        timeout: float = 1800.0,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.TaskRun:
        """Polls until the task run has finished (completed, failed or canceled; a paused run keeps waiting for a
        person, a queued one for its turn) and returns it with its result. Pass the run that ``run`` returned, or the
        task's and the run's ids::

            run = bx.tasks.run(task["id"], variables={"category": "Poetry"})
            done = bx.tasks.wait_for_run(run)          # done["result"]: the JSON answer with an output schema

        NotFoundError when the run is not in the task's history; BoxlineTimeoutError after ``timeout`` seconds."""
        if isinstance(task_id, dict):
            task_id, task_run_id = task_id["taskId"], task_id["id"]
        if not task_run_id:
            raise TypeError("wait_for_run needs the task run: wait_for_run(run) or wait_for_run(task_id, task_run_id)")
        deadline = time.monotonic() + timeout
        while True:
            # There is no GET for one task run: the unfinished ones are a short list, and a run missing from it has finished.
            is_open = False
            for r in self.runs(task_id, status=_TASK_RUN_OPEN, limit=100, options=options):
                if r["id"] == task_run_id:
                    is_open = True
                    break
            if not is_open:
                for r in self.runs(task_id, limit=100, options=options):
                    if r["id"] == task_run_id:
                        return r
                raise NotFoundError(404, ErrorCode.NOT_FOUND, f"task run {task_run_id} is not in the run history of task {task_id}")
            if time.monotonic() > deadline:
                raise BoxlineTimeoutError("the task run did not finish in time")
            _sleep(poll)


# ---------------------------------------------------------------- extensions


class Extensions:
    """Chrome extensions (Manifest V3) to start sessions with (``extensions=[id]``; plan feature ``extensions``). An
    extension sees every page and every typed value in the sessions that use it: upload only extensions you trust."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def upload(self, zip: Union[bytes, bytearray, str, "os.PathLike[str]"], *, options: Optional[RequestOptions] = None) -> t.Extension:
        """Uploads an unpacked extension as a zip, at most 10 MB: its bytes, or a file path. It is checked before it is
        stored (InvalidExtensionError says why; PayloadTooLargeError over 10 MB; LimitReachedError beyond 100
        extensions). An Idempotency-Key is sent, so a retry never stores it twice."""
        if isinstance(zip, (bytes, bytearray)):
            content = bytes(zip)
        else:
            with open(os.fspath(zip), "rb") as f:
                content = f.read()
        headers = {"content-type": "application/zip", **((options or {}).get("headers") or {})}
        res = self._c._send("POST", "/v1/extensions", content=content, options={**(options or {}), "headers": headers})
        return _parse(res)

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.Extension]:
        """The project's extensions, newest first."""
        return self._c._list("/v1/extensions", {"limit": limit, "after": after}, lambda e: e, options)

    def get(self, extension_id: str, *, options: Optional[RequestOptions] = None) -> t.Extension:
        return self._c._json("GET", f"/v1/extensions/{seg(extension_id)}", options=options)

    def delete(self, extension_id: str, *, options: Optional[RequestOptions] = None) -> None:
        """Deletes it; sessions already running with it keep it until they move or resume."""
        self._c._json("DELETE", f"/v1/extensions/{seg(extension_id)}", options=options)


# ---------------------------------------------------------------- agent


class Agent:
    """Agent runs: a model (Claude, GPT, Grok or Gemini) drives the session's browser and/or shell to finish a task. Its
    tools follow the session: ``run(task, session={"browser": False, "shell": True})`` is a shell-only run."""

    def __init__(self, client: Boxline) -> None:
        self._c = client

    def models(self, *, options: Optional[RequestOptions] = None) -> t.AgentModels:
        """Providers and models you can choose, with prices and whether each is configured on the server."""
        return self._c._json("GET", "/v1/agent/models", options=options)

    def run(
        self,
        task: str,
        session_id: Optional[str] = None,
        session: Optional[t.SessionSpec] = None,
        max_steps: Any = NOT_GIVEN,
        effort: Optional[str] = None,
        keep_session: Optional[bool] = None,
        provider: Optional[str] = None,
        model: Optional[str] = None,
        variables: Optional[Dict[str, t.AgentVariable]] = None,
        mode: Optional[str] = None,
        allow_with_extensions: Optional[bool] = None,
        output: Optional[t.OutputSchema] = None,
        credentials: Optional[Sequence[str]] = None,
        max_cost_usd: Optional[float] = None,
        max_consecutive_errors: Optional[int] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.AgentRunStarted:
        """Starts a run and returns ``{"id", "status", "sessionId", "provider", "model"}`` right away (an
        Idempotency-Key is sent, so a retry never starts a second run). The run's tools follow its session.

        ``session``: the run's own session, a ``SessionSpec`` dict with the API's names, as ``sessions.create`` takes
        its arguments: a browser only (the default), a shell only (``{"browser": False, "shell": True}``) or both,
        with its ``proxy``, ``captcha`` ("ask", "ignore" or "solve"), ``extensions``, ``profile``, ``blockAds``,
        ``timeout`` and so on (see ``types.SessionSpec``). ``session_id`` works in an existing session instead (its own
        settings apply); giving both is a 400. The run's session lasts 1800 seconds unless ``session["timeout"]`` says
        otherwise (or the plan's maximum when shorter); a run stops with ``session_timeout`` when its session's time ends.
        ``session["credentials"]`` are exported into the session's shell; the run's ``credentials`` below are what the AI
        may type.

        ``variables`` are secrets and other values the agent may type as ``%name%`` placeholders (e.g. a task
        "sign in with %email% and %password%"): ``{"email": "me@example.com", "password": {"value": "...",
        "origins": ["https://example.com"]}, "token": {"value": "...", "shell": True}}``. The model is told the
        names only. A value is filled in only where the model types text (browser_type) or picks an option
        (browser_select), never into URLs, selectors or keys; shell commands only with ``"shell": True``.
        ``origins`` limits typing it to fields on those sites (scheme, host and port; ``"https://*.example.com"`` for
        subdomains), recommended for passwords. Values are replaced by their placeholder in everything the model
        sees and the run stores, and kept in memory for the run only. Up to 50; names are letters, digits and ``_``
        (not starting with a digit, 64 characters at most); values up to 8000 characters and 64 KB together
        (shorter than 3 characters are filled in but not hidden).

        ``mode="computer"``: the model drives the page with its provider's own computer-use tool on screenshots (models
        with ``supportsComputerUse`` in ``agent.models()``; 400 otherwise, or without a browser). Tool and handover steps
        carry the model's ``thought``.

        ``variables`` in a session with extensions (which can read every typed value) are refused
        (VariablesWithExtensionsError) unless ``allow_with_extensions=True``.

        ``output`` (structured output): a JSON Schema the answer must match, e.g. ``{"type": "object", "properties":
        {"title": {"type": "string"}}, "required": ["title"]}``. The finished run's ``result`` is then the JSON answer
        (a dict, list, …) and ``resultText`` a one-sentence summary; an answer that still does not match after one
        repair try fails the run with ``errorCode`` "output_invalid". A schema that is not valid, or over 32 KB, is a 400.

        ``credentials``: credentials as placeholders, exactly like ``variables``, each with the credential's own
        ``origins`` and ``shell`` rule (scope "agent" or "all"; CredentialNotAllowedError for scope "shell"): ``%NAME%``
        for a secret, ``%NAME.username%``, ``%NAME.password%`` and ``%NAME.otp%`` for a password. An explicit variable
        with the same name wins. A password credential linked to the session's ``profile`` (``profiles.update``) is added
        as if it were listed in ``credentials``.

        The run's ``steps`` include ``handover``/``resume`` steps and, for a CAPTCHA pause, ``captcha`` steps:
        ``state`` "solving" or "waiting" (with ``kind``, ``host`` and, when waiting, ``reason``), then "solved"
        with ``by`` ("auto" or "person") and ``ms``; messages you sent (``send_message``) are ``message`` steps.

        Limits: ``max_steps`` (1-1000, default 30 when not passed; ``max_steps=None`` means no step limit: the run goes
        until it is done or its session's time ends it), ``max_cost_usd`` (0.01-100 USD of model cost, checked before
        each model call; default none), ``max_consecutive_errors`` (tool errors in a row, 1-20, default 5), and the same
        call with the same result 5 times. At one of these the run ends with ``errorCode`` ``max_steps``, ``max_cost``,
        ``too_many_errors`` or ``no_progress``, ``resultText`` says what is done and what is left, and ``resumable``
        says until when ``resume`` can carry it on (its own session is kept that long)."""
        body = clean(
            {
                "task": task,
                "sessionId": session_id,
                "session": session,
                "effort": effort,
                "keepSession": keep_session,
                "provider": provider,
                "model": model,
                "variables": variables,
                "mode": mode,
                "allowWithExtensions": allow_with_extensions,
                "output": output,
                "credentials": as_list(credentials),
                "maxCostUsd": max_cost_usd,
                "maxConsecutiveErrors": max_consecutive_errors,
            }
        )
        if max_steps is not NOT_GIVEN:
            body["maxSteps"] = max_steps  # None: no step limit
        return self._c._json("POST", "/v1/agent/runs", json=body, options=options)

    def get(self, run_id: str, *, options: Optional[RequestOptions] = None) -> t.AgentRun:
        return self._c._json("GET", f"/v1/agent/runs/{seg(run_id)}", options=options)

    def list(self, limit: Optional[int] = None, after: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> Pager[t.AgentRun]:
        """Runs, newest first."""
        return self._c._list("/v1/agent/runs", {"limit": limit, "after": after}, lambda r: r, options)

    def pause(self, run_id: str, reason: Optional[str] = None, *, options: Optional[RequestOptions] = None) -> t.AgentRun:
        """Pauses the run: the agent finishes its current action, then waits (status ``paused``), so a person can act in
        the live view or the terminal (a CAPTCHA, a 2FA code, a choice). Works on every kind of run, a shell-only one too.
        ``resume`` goes on. RunNotLiveError when its server stopped; a BoxlineError with code ``invalid_state`` unless the
        run is running."""
        return self._c._json("POST", f"/v1/agent/runs/{seg(run_id)}/pause", json=clean({"reason": reason}), options=options)

    def resume(
        self,
        run_id: str,
        note: Optional[str] = None,
        max_steps: Any = NOT_GIVEN,
        max_cost_usd: Any = NOT_GIVEN,
        variables: Optional[Dict[str, Union[str, Dict[str, str]]]] = None,
        *,
        options: Optional[RequestOptions] = None,
    ) -> t.AgentRun:
        """Keeps a run going: the SAME run, one job and one run id (its steps and usage add up). It works on

        - a paused run (after ``pause``, a CAPTCHA, or the agent asking for help): ``note`` (an extra note for the model, at
          most 2000 characters) is told to the agent with the news that a person had control, and it looks at the page
          again;
        - a run that stopped early (its ``resumable`` is set: it used all its steps (``max_steps``), reached its
          ``max_cost_usd``, had too many tool errors in a row, repeated itself, or its API server restarted):
          ``max_steps`` (1-1000; ``None`` means no step limit; default: the run's own), ``max_cost_usd`` (the model cost
          this stretch may add; default: the run's own; ``None``: none), ``note`` (an extra note for the model) and
          ``variables`` (the run's variables again: their values are never stored; every name, as text or
          ``{"value": ...}``; MissingVariablesError when one is missing). A stopped session is resumed first.

        NotResumableError when the run is neither (it is running, completed, canceled, failed for another reason, or its
        window passed), RunNotLiveError when its server stopped. An Idempotency-Key is sent, so a retry never resumes it
        twice::

            run = bx.agent.resume(run["id"], max_steps=30, note="The CSV is downloaded already")"""
        body: Dict[str, Any] = clean({"note": note, "variables": variables})
        if max_steps is not NOT_GIVEN:
            body["maxSteps"] = max_steps
        if max_cost_usd is not NOT_GIVEN:
            body["maxCostUsd"] = max_cost_usd
        return self._c._json("POST", f"/v1/agent/runs/{seg(run_id)}/resume", json=body, options=options)

    def cancel(self, run_id: str, *, options: Optional[RequestOptions] = None) -> t.AgentRun:
        """Stops the run for good."""
        return self._c._json("POST", f"/v1/agent/runs/{seg(run_id)}/cancel", options=options)

    def send_message(self, run_id: str, text: str, *, options: Optional[RequestOptions] = None) -> t.AgentMessageSent:
        """Tells a working run something (1-2000 characters) without taking the browser: the agent reads it at its next
        step (a model call or tool under way is not interrupted), and it shows as a ``message`` step. A run waiting for
        your help (``ask_user_for_help``) takes it as the answer and goes on. At most 50 per run (TooManyMessagesError);
        a BoxlineError with code ``invalid_state`` once the run has finished."""
        return self._c._json("POST", f"/v1/agent/runs/{seg(run_id)}/messages", json={"text": text}, options=options)

    def stream(self, run_id: str, *, options: Optional[RequestOptions] = None) -> Iterator[t.AgentRunEvent]:
        """Yields the run's events as they happen: its steps so far, then new steps, the model's ``thought`` as soon as
        its reply arrives, ``status`` changes, live shell ``exec``/``output``, and a final ``done`` event, after which the
        iteration ends."""
        res = self._c._stream("GET", f"/v1/agent/runs/{seg(run_id)}/events/stream", options=options)
        try:
            for event in _sse(res.iter_lines()):
                yield event
                if event.get("type") == "done":
                    return
        finally:
            res.close()

    def wait(self, run_id: str, poll: float = 1.0, timeout: float = 1800.0, *, options: Optional[RequestOptions] = None) -> t.AgentRun:
        """Polls until the run finishes (a paused run keeps waiting for the user)."""
        deadline = time.monotonic() + timeout
        while True:
            run = self.get(run_id, options=options)
            if run["status"] not in ("running", "paused"):
                return run
            if time.monotonic() > deadline:
                raise BoxlineTimeoutError("the agent run did not finish in time")
            _sleep(poll)
